-- Trim explicit oversized selections in other environments as well.
update public.product_templates set enabled_colors=enabled_colors[1:25] where cardinality(enabled_colors)>25;
alter table public.product_templates add constraint template_max_25_colors
  check (enabled_colors is null and catalog_product_id is null or
    enabled_colors is not null and cardinality(enabled_colors) between 1 and 25) not valid;
